use std::collections::HashMap
use std::fs

fn bal(m: HashMap<string, int>, k: string) -> int {
    match m.get(k) {
        Some(v) => v,
        None => 0,
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut accts: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 2 {
            continue
        }
        let cmd = parts[0]
        if cmd == "open" && parts.len() >= 3 {
            let name = parts[1]
            let amt = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if accts.contains_key(name) {
                println("error: duplicate account")
            } else {
                accts.insert(name, amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && parts.len() >= 3 {
            let name = parts[1]
            let amt = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !accts.contains_key(name) {
                println("error: unknown account ${name}")
            } else {
                let b = bal(accts, name)
                if cmd == "deposit" {
                    accts.insert(name, b + amt)
                    println("ok")
                } else if b < amt {
                    println("error: insufficient funds")
                } else {
                    accts.insert(name, b - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && parts.len() >= 4 {
            let from = parts[1]
            let to = parts[2]
            let amt = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !accts.contains_key(from) {
                println("error: unknown account ${from}")
            } else if !accts.contains_key(to) {
                println("error: unknown account ${to}")
            } else if from == to {
                println("error: same account")
            } else {
                let fb = bal(accts, from)
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    let tb = bal(accts, to)
                    accts.insert(from, fb - amt)
                    accts.insert(to, tb + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" {
            let name = parts[1]
            if !accts.contains_key(name) {
                println("error: unknown account ${name}")
            } else {
                println("${bal(accts, name)}")
            }
        }
    }
    let mut keys: Vec<string> = accts.keys().collect()
    keys.sort()
    for k in keys {
        println("${k} ${bal(accts, k)}")
    }
}

